with open("region.fasta") as f:
    lines = f.read().splitlines()
seq = "".join(l.strip() for l in lines[1:])

def rc(s):
    comp = {'A':'T','T':'A','G':'C','C':'G'}
    return "".join(comp[c] for c in reversed(s))

def orfs(s, minaa=30):
    stops = {'TAA','TAG','TGA'}
    res = []
    for strand, sq in (('+', s), ('-', rc(s))):
        for frame in range(3):
            i = frame
            start = None
            j = frame
            # walk codons
            start = None
            for k in range(frame, len(sq)-2, 3):
                cod = sq[k:k+3]
                if start is None and cod == 'ATG':
                    start = k
                elif start is not None and cod in stops:
                    length_aa = (k - start)//3
                    if length_aa >= minaa:
                        if strand == '+':
                            res.append((strand, start+1, k+2, length_aa))
                        else:
                            # convert coords to forward strand
                            # positions in rc: k -> forward pos len(sq)-k-1 etc.
                            fstart = len(sq) - (k+2)
                            fend = len(sq) - start
                            res.append((strand, fstart+1, fend, length_aa))
                    start = None
    return res

