def rc(s):
    c={'A':'T','T':'A','G':'C','C':'G'}; return "".join(c[x] for x in reversed(s))

# Dinucleotide-preserving shuffle (order-1 Markov)
def markov_shuffle(s):
    from collections import defaultdict
    trans=defaultdict(list)
    for i in range(len(s)-1):
        trans[s[i]].append(s[i+1])
    out=[random.choice(s)]
    for _ in range(len(s)-1):
        out.append(random.choice(trans[out[-1]]))
    return "".join(out)

def maxorf(s):
    best=0
    for sq in (s,rc(s)):
        for fr in range(3):
            start=None
            for k in range(fr,len(sq)-2,3):
                cod=sq[k:k+3]
                if start is None:
                    if cod=='ATG': start=k
                elif cod in stops:
                    best=max(best,(k-start)//3); start=None
    return best

random.seed(2)
res=[maxorf(markov_shuffle(seq)) for _ in range(200)]
res.sort()
print("Markov-shuffle max ORF: median",res[100],"95%",res[190],"max",res[-1],"P(>=428)=",sum(1 for x in res if x>=428)/len(res))
