with open("region.fasta") as f:
    lines=f.read().splitlines()
seq="".join(l.strip() for l in lines[1:]).upper()
n=len(seq)
def rc(s):
    c={'A':'T','T':'A','G':'C','C':'G'}; return "".join(c[x] for x in reversed(s))
stops={'TAA','TAG','TGA'}

def runs(sq, mincod=80):
    out=[]
    for fr in range(3):
        cur_start=fr
        prev=fr
        k=fr
        while k < len(sq)-2:
            if sq[k:k+3] in stops:
                if (k-prev)//3 >= mincod:
                    out.append((prev, k, (k-prev)//3))
                prev=k+3
            k+=3
        if (len(sq)-3-prev)//3 >= mincod:
            out.append((prev, len(sq)-3, (len(sq)-3-prev)//3))
    return out

print("=== ORF-scale stop-free stretches (>=80 codons) ===")
for strand,sq in (('+',seq),('-',rc(seq))):
    for st,en,cod in runs(sq,80):
        if strand=='+':
            fs,fe=st+1,en+2
        else:
            fs,fe=n-(en+2)+1, n-st
        print(f"{strand} strand  forward {fs}-{fe}  length {cod} codons ({cod*3} bp)")

# coding coverage for chosen ORFs
